    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int Xi = Integer.parseInt(st.nextToken());
        int Yi = Integer.parseInt(st.nextToken());
        int Xf = Integer.parseInt(st.nextToken());
        int Yf = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(br.readLine().trim());
        int V = N + 2;
        int[] x1 = new int[V];
        int[] y1 = new int[V];
        int[] x2 = new int[V];
        int[] y2 = new int[V];

        // Start point as a degenerate rectangle
        x1[0] = x2[0] = Xi;
        y1[0] = y2[0] = Yi;
        // End point as a degenerate rectangle
        x1[1] = x2[1] = Xf;
        y1[1] = y2[1] = Yf;

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            int X1 = Integer.parseInt(st.nextToken());
            int Y1 = Integer.parseInt(st.nextToken());
            int X2 = Integer.parseInt(st.nextToken());
            int Y2 = Integer.parseInt(st.nextToken());
            x1[i + 2] = X1;
            y1[i + 2] = Y1;
            x2[i + 2] = X2;
            y2[i + 2] = Y2;
        }

        long[] dist = new long[V];
        boolean[] visited = new boolean[V];
        Arrays.fill(dist, Long.MAX_VALUE / 2);
        dist[0] = 0;

        for (int i = 0; i < V; i++) {
            int u = -1;
            long min = Long.MAX_VALUE / 2;
            for (int j = 0; j < V; j++) {
                if (!visited[j] && dist[j] < min) {
                    min = dist[j];
                    u = j;
                }
            }
            if (u == -1) break;
            visited[u] = true;
            if (u == 1) break;

            for (int v = 0; v < V; v++) {
                if (!visited[v]) {
                    long dx = Math.max(0, Math.max(x1[u], x1[v]) - Math.min(x2[u], x2[v]));
                    long dy = Math.max(0, Math.max(y1[u], y1[v]) - Math.min(y2[u], y2[v]));
                    long w = dx + dy;
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                    }
                }
            }
        }

        System.out.println(dist[1]);
    }
}
